css:
.ss-cl{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px}
.ss-cl--compare{margin:8px 0 24px}
.ss-cl--group{margin-bottom:8px}
.ss-cl__card{border:1px solid var(--line)}
.ss-cl--compare .ss-cl__card{padding:24px}
.ss-cl--group .ss-cl__card{padding:22px 24px;margin-bottom:16px}
.ss-cl__t{font:800 19px/1.3 var(--font-heading);color:var(--ink);text-transform:none;margin:30px 0 12px}
.ss-cl--group .ss-cl__t{margin:0 0 12px}
.ss-cl__p{font-size:15px;line-height:1.8;color:var(--body-text);margin:0 0 12px}
.ss-cl__list{margin:0 0 20px;padding-left:20px}
.ss-cl__list li{font-size:16px;line-height:1.75;color:var(--body-text);margin-bottom:6px}
.ss-cl--interval{grid-template-columns:repeat(4,minmax(0,1fr));margin:8px 0 24px}
.ss-cl--interval .ss-cl__card{padding:22px}
.ss-cl--interval .ss-cl__t{font:700 11px/1 var(--font-body);letter-spacing:.1em;text-transform:uppercase;color:var(--accent);margin:0 0 10px}
.ss-cl--interval .ss-cl__list{margin:0;padding-left:18px}
.ss-cl--feature{grid-template-columns:repeat(3,minmax(0,1fr));margin-bottom:20px}
.ss-cl--feature2{margin-bottom:20px}
.ss-cl--feature .ss-cl__card,.ss-cl--feature2 .ss-cl__card{padding:22px}
.ss-cl--feature .ss-cl__t,.ss-cl--feature2 .ss-cl__t{margin:0 0 12px}
.ss-cl--feature .ss-cl__p,.ss-cl--feature2 .ss-cl__p{margin:0}
.ss-cl__p a{color:var(--accent)}
.ss-cl--spec{margin-bottom:20px}
.ss-cl--spec .ss-cl__card{padding:22px}
.ss-cl--spec .ss-cl__t{margin:0 0 12px}
.ss-cl--spec .ss-cl__list{margin:0;padding-left:18px}
.ss-cl--spec .ss-cl__list li{font-size:15px}
.ss-cl--spec .ss-cl__list li:last-child{margin-bottom:0}
.ss-cl__list strong{color:var(--ink)}
.ss-cl--series,.ss-cl--numbered{grid-template-columns:repeat(3,minmax(0,1fr));margin-bottom:24px}
.ss-cl--series2{margin-bottom:20px}
.ss-cl--series .ss-cl__card,.ss-cl--series2 .ss-cl__card,.ss-cl--numbered .ss-cl__card{padding:20px}
.ss-cl--series .ss-cl__t,.ss-cl--series2 .ss-cl__t,.ss-cl--numbered .ss-cl__t{font:700 11px/1 var(--font-body);letter-spacing:.14em;text-transform:uppercase;color:var(--accent);margin:0 0 12px}
.ss-cl--series .ss-cl__p,.ss-cl--series2 .ss-cl__p,.ss-cl--numbered .ss-cl__p{margin:0}
.ss-cl--numbered .ss-cl__p{font:800 17px/1.3 var(--font-heading);color:var(--ink);text-transform:none}
@media (max-width:1100px){.ss-cl--feature,.ss-cl--series,.ss-cl--numbered{grid-template-columns:repeat(2,minmax(0,1fr))}.ss-cl{grid-template-columns:minmax(0,1fr)}.ss-cl--interval{grid-template-columns:repeat(2,minmax(0,1fr))}}
@media (max-width:640px){.ss-cl--interval,.ss-cl--feature,.ss-cl--series,.ss-cl--feature2,.ss-cl--series2,.ss-cl--numbered{grid-template-columns:minmax(0,1fr)}}
.ss-cl--type,.ss-cl--option{margin:0 0 20px}
.ss-cl--option{grid-template-columns:repeat(3,minmax(0,1fr));gap:24px}
.ss-cl--type .ss-cl__card,.ss-cl--option .ss-cl__card{padding:26px;margin:0}
.ss-cl--type .ss-cl__t{margin:0 0 12px}
.ss-cl--option .ss-cl__t{margin:0 0 10px}
.ss-cl--type .ss-cl__p,.ss-cl--option .ss-cl__p{font-size:15px;line-height:1.7;margin:0 0 14px}
.ss-cl--type .ss-cl__lead{font:700 14px/1.6 var(--font-body);color:var(--ink);margin:0 0 8px}
.ss-cl--option .ss-cl__lead{font:700 10px/1 var(--font-body);letter-spacing:.12em;text-transform:uppercase;color:var(--accent);margin:0 0 8px}
.ss-cl--type .ss-cl__list{margin:0 0 16px;padding-left:18px}
.ss-cl--option .ss-cl__list{margin:0;padding-left:18px}
.ss-cl--type .ss-cl__list li{font-size:15px}
.ss-cl--option .ss-cl__list li{font-size:14px}
@media (max-width:1100px){.ss-cl--type{grid-template-columns:repeat(2,minmax(0,1fr))}.ss-cl--option{grid-template-columns:repeat(2,minmax(0,1fr))}}
@media (max-width:640px){.ss-cl--type,.ss-cl--option{grid-template-columns:minmax(0,1fr)}}
.ss-cl--type3{grid-template-columns:repeat(3,minmax(0,1fr));margin:0 0 20px}
.ss-cl--type3 .ss-cl__card{padding:24px}
.ss-cl--type3 .ss-cl__t{margin:0 0 10px}
.ss-cl--type3 .ss-cl__p{font-size:15px;line-height:1.65;margin:0}
.ss-cl--cost{grid-template-columns:minmax(0,1fr);gap:8px;margin:0 0 20px}
.ss-cl--cost .ss-cl__card{padding:24px}
.ss-cl--cost .ss-cl__t{margin:0 0 10px}
.ss-cl--cost .ss-cl__p{font-size:15px;line-height:1.8;margin:0 0 10px}
.ss-cl--cost .ss-cl__list{margin:0;padding-left:18px}
.ss-cl--cost .ss-cl__list li{font-size:15px}
.ss-cl__o{font-size:14px;line-height:1.8;color:var(--body-text);margin:10px 0 0}
.ss-cl--num,.ss-cl--num-wide{margin:0 0 20px}
.ss-cl--num-wide{grid-template-columns:minmax(0,1fr)}
.ss-cl--num .ss-cl__card,.ss-cl--num-wide .ss-cl__card{padding:24px}
.ss-cl__n{display:block;font:800 22px/1 var(--font-heading);color:var(--accent);margin-bottom:10px}
.ss-cl--num .ss-cl__t,.ss-cl--num-wide .ss-cl__t{margin:0 0 10px}
.ss-cl--num .ss-cl__p,.ss-cl--num-wide .ss-cl__p{font-size:14px;line-height:1.8;margin:0}
.ss-cl--num-wide .ss-cl__p{margin:0 0 8px}
.ss-cl--num .ss-cl__list,.ss-cl--num-wide .ss-cl__list{margin:0;padding-left:18px}
.ss-cl--num .ss-cl__list li,.ss-cl--num-wide .ss-cl__list li{font-size:14px}
@media (max-width:1100px){.ss-cl--type3{grid-template-columns:repeat(2,minmax(0,1fr))}.ss-cl--num{grid-template-columns:repeat(2,minmax(0,1fr))}}
@media (max-width:640px){.ss-cl--type3,.ss-cl--num{grid-template-columns:minmax(0,1fr)}}
